    fprintf(stderr, "-p [address:]port\n");
    fprintf(stderr, "		Listen on specified tcp port (and optionally address),\n");
    fprintf(stderr, "		up to 10 can be specified\n");
    fprintf(stderr, "		(default port is 22 if none specified)\n");
    fprintf(stderr, "-P PidFile	Create pid file PidFile\n");
    fprintf(stderr, "		(default /var/run/dropbear.pid)\n");
    fprintf(stderr, "-l <interface>\n");
    fprintf(stderr, "		interface to bind on\n");
    fprintf(stderr, "-i		Start for inetd\n");
