    const char *optstring = "b:r:D:RFemwG:sgBtT:jka:c:p:P:l:iW:K:I:zV";

    while ((opt = getopt(argc, argv, optstring)) != -1) {
        switch (opt) {
            case 'V':
                print_version();
                return 0;
            case '?':
                print_help(progname);
                return 1;
            default:
                break;
        }
    }

    if (optind < argc) {
        fprintf(stderr, "Invalid argument: %s\n", argv[optind]);
        // Wait, the original shows "Early exit: Invalid argument: ..."
