    log_message("Failed loading /etc/dropbear/dropbear_ecdsa_host_key");
    log_message("Failed loading /etc/dropbear/dropbear_ed25519_host_key");
    log_message("Early exit: No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.");

    return 1;
}
EOF
