    fprintf(stderr, "-j		Disable local port forwarding\n");
    fprintf(stderr, "-k		Disable remote port forwarding\n");
    fprintf(stderr, "-a		Allow connections to forwarded ports from any host\n");
    fprintf(stderr, "-c command	Force executed command\n");
    fprintf(stderr, "-p [address:]port\n");
    fprintf(stderr, "		Listen on specified tcp port (and optionally address),\n");
    fprintf(stderr, "		up to 10 can be specified\n");
    fprintf(stderr, "		(default port is 22 if none specified)\n");
    fprintf(stderr, "-P PidFile	Create pid file PidFile\n");
    fprintf(stderr, "		(default /var/run/dropbear.pid)\n");
    fprintf(stderr, "-l <interface>\n");
    fprintf(stderr, "		interface to bind on\n");
    fprintf(stderr, "-i		Start for inetd\n");
    fprintf(stderr, "-W <receive_window_buffer> (default 24576, larger may be faster, max 10MB)\n");
    fprintf(stderr, "-K <keepalive>  (0 is never, default 0, in seconds)\n");
    fprintf(stderr, "-I <idle_timeout>  (0 is never, default 0, in seconds)\n");
    fprintf(stderr, "-z    disable QoS\n");
    fprintf(stderr, "-V    Version\n");
