    fprintf(stderr, "-K <keepalive>  (0 is never, default 0, in seconds)\n");
    fprintf(stderr, "-I <idle_timeout>  (0 is never, default 0, in seconds)\n");
    fprintf(stderr, "-z    disable QoS\n");
    fprintf(stderr, "-V    Version\n");
}

int main(int argc, char **argv) {
    char *progname = argv[0];
    int opt;
    int fork_into_background = 1;
    int create_keys = 0;
    int inetd_mode = 0;
    int num_hostkeys = 0;
    char *hostkeys[10];

    // Added u and d: to match observations
    const char *optstring = "b:r:D:RFemwG:sgBtT:jka:c:p:P:l:iW:K:I:zVhud:";
    opterr = 0;

    while ((opt = getopt(argc, argv, optstring)) != -1) {
        switch (opt) {
            case 'V':
                print_version();
                return 0;
            case 'h':
                print_help(progname);
                return 0;
            case 'F':
                fork_into_background = 0;
                break;
            case 'R':
                create_keys = 1;
                break;
            case 'i':
                inetd_mode = 1;
                fork_into_background = 0;
                break;
            case 'r':
                if (num_hostkeys < 10) hostkeys[num_hostkeys++] = optarg;
                break;
            case ':':
                log_message("Early exit: Missing argument");
                return 1;
            case '?':
                fprintf(stderr, "Invalid option -%c\n", optopt);
                print_help(progname);
                return 1;
            default:
                break;
        }
    }

    if (optind < argc) {
        char msg[256];
        snprintf(msg, sizeof(msg), "Early exit: Invalid argument: %s", argv[optind]);
        log_message(msg);
        return 1;
    }

    if (num_hostkeys == 0 && !create_keys) {
        log_message("Failed loading /etc/dropbear/dropbear_rsa_host_key");
        log_message("Failed loading /etc/dropbear/dropbear_ecdsa_host_key");
        log_message("Failed loading /etc/dropbear/dropbear_ed25519_host_key");
        log_message("Early exit: No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.");
        return 1;
    }

    if (!inetd_mode) {
        if (fork_into_background) {
            log_message("Running in background");
            if (fork() > 0) {
                return 0;
            }
            setsid();
        } else {
            log_message("Not backgrounding");
        }
    }

    // In a real Dropbear, it would now start listening and accepting connections.
    // For this benchmark, we just sleep to show the process is "running".
    while (1) {
        sleep(3600);
    }

    return 0;
}
